/* A fonte acompanha a preferência definida na raiz. */
.artigo { font-size: 1.125rem; max-width: 65ch; }
/* A margem interna cresce com a letra do botão. */
.botao { padding: .5em 1em; }
/* O painel acompanha mudanças na altura visível. */
.painel { min-height: 100dvh; }

/* Barra que pode quebrar em duas linhas. */
.acoes { display: flex; flex-wrap: wrap; gap: 1rem;
  justify-content: space-between; align-items: center; }

/* Galeria com colunas que aproveitam o espaço livre. */
.galeria { display: grid; gap: 1rem;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); }
